	@Test
	void lazyValueSurvivesCommitAndGcRevisionInvalidation() throws Exception {
		IRI anchor = FACTORY.createIRI("urn:lifecycle:anchor:", "reader");
		IRI expected = FACTORY.createIRI("urn:lifecycle:old:", "value");
		long anchorId = store(anchor);
		long expectedId = store(expected);
		valueStore.clearCaches();

		try (ValueStoreMaterializer materializer = new ValueStoreMaterializer(valueStore)) {
			// Acquire the retained reader with a separate value, leaving the value under test unresolved.
			assertEquals(anchor.stringValue(), valueStore.getLazyValue(anchorId, materializer).stringValue());
			LmdbIRI lazy = (LmdbIRI) valueStore.getLazyValue(expectedId, materializer);
			ValueStoreRevision.Lazy originalRevision = valueStore.getLazyRevision();
			assertSame(originalRevision, ValueStoreMaterializer.originalRevisionOf(lazy.getValueStoreRevision()));
			long oldRevisionId = valueStore.getRevision().getRevisionId();

			valueStore.startTransaction(true);
			try {
				valueStore.gcIds(Set.of(expectedId), new HashSet<>());
				valueStore.commit();
			} catch (Exception e) {
				valueStore.rollback();
				throw e;
			}

			assertNotEquals(oldRevisionId, valueStore.getRevision().getRevisionId(),
					"GC must invalidate the value-store revision");
			IRI current = FACTORY.createIRI("urn:lifecycle:current:", "value");
			long currentId = store(current);
			valueStore.clearCaches();
			ValueStoreRevision.Lazy currentRevision = valueStore.getLazyRevision();
			LmdbIRI currentLazy = (LmdbIRI) valueStore.getLazyValue(currentId, materializer);
			assertNotEquals(originalRevision, currentRevision);
			assertSame(currentRevision, ValueStoreMaterializer.originalRevisionOf(currentLazy.getValueStoreRevision()));
			assertEquals(current.stringValue(), currentLazy.stringValue());
			valueStore.forceEvictionOfValues();
			valueStore.startTransaction(true);
			valueStore.commit();

			assertEquals(expected.stringValue(), lazy.stringValue(),
					"A lazy value must retain its original revision across GC invalidation");
		}
	}

	@Test
	void oldLazyNestedTripleCreatesChildrenThatOutliveRevisionChange() throws Exception {
		IRI anchor = FACTORY.createIRI("urn:lifecycle:nested-anchor:", "reader");
		BNode nestedSubject = FACTORY.createBNode("nested-bnode");
		IRI nestedPredicate = FACTORY.createIRI("urn:lifecycle:nested:", "predicate");
		Literal nestedObject = FACTORY.createLiteral(
				"a directed literal that is deliberately too large to inline", "he", Literal.BaseDirection.RTL);
		TripleTerm nested = FACTORY.createTripleTerm(nestedSubject, nestedPredicate, nestedObject);
		IRI outerSubject = FACTORY.createIRI("urn:lifecycle:outer:", "subject");
		IRI outerPredicate = FACTORY.createIRI("urn:lifecycle:outer:", "predicate");
		TripleTerm outer = FACTORY.createTripleTerm(outerSubject, outerPredicate, nested);
		long anchorId = store(anchor);
		long outerId = store(outer);
		valueStore.clearCaches();

		LmdbTripleTerm lazyOuter;
		Literal lazyNestedObject;
		try (ValueStoreMaterializer materializer = new ValueStoreMaterializer(valueStore)) {
			assertEquals(anchor.stringValue(), valueStore.getLazyValue(anchorId, materializer).stringValue());
			lazyOuter = (LmdbTripleTerm) valueStore.getLazyValue(outerId, materializer);
			ValueStoreRevision.Lazy originalRevision = valueStore.getLazyRevision();
			assertSame(originalRevision, ValueStoreMaterializer.originalRevisionOf(lazyOuter.getValueStoreRevision()));
			long oldRevisionId = valueStore.getRevision().getRevisionId();

			valueStore.startTransaction(true);
			try {
				valueStore.gcIds(Set.of(outerId), new HashSet<>());
				valueStore.commit();
			} catch (Exception e) {
				valueStore.rollback();
				throw e;
			}
			assertNotEquals(oldRevisionId, valueStore.getRevision().getRevisionId());
			IRI current = FACTORY.createIRI("urn:lifecycle:nested-current:", "value");
			long currentId = store(current);
			valueStore.clearCaches();
			ValueStoreRevision.Lazy currentRevision = valueStore.getLazyRevision();
			LmdbIRI currentLazy = (LmdbIRI) valueStore.getLazyValue(currentId, materializer);
			assertNotEquals(originalRevision, currentRevision);
			assertSame(currentRevision, ValueStoreMaterializer.originalRevisionOf(currentLazy.getValueStoreRevision()));
			assertEquals(current.stringValue(), currentLazy.stringValue());

			TripleTerm lazyNested = (TripleTerm) lazyOuter.getObject();
			assertEquals(nestedSubject.getID(), ((BNode) lazyNested.getSubject()).getID());
			lazyNestedObject = (Literal) lazyNested.getObject();
			assertSame(originalRevision,
					ValueStoreMaterializer.originalRevisionOf(((LmdbValue) lazyNestedObject).getValueStoreRevision()));
		}

		// The scalar child was created from the old nested triple after the revision changed. It must still resolve
		// after
		// the dataset-scoped materializer has closed.
		assertEquals(nestedObject.getLabel(), lazyNestedObject.getLabel());
		assertFalse(lazyNestedObject.getLanguage().isEmpty(), "the nested child must remain a language literal");
		assertEquals(nestedObject.getLanguage(), lazyNestedObject.getLanguage());
		assertEquals(nestedObject.getBaseDirection(), lazyNestedObject.getBaseDirection());
		assertEquals(nestedObject.getDatatype(), lazyNestedObject.getDatatype());
	}

	@Test
	void ownerThreadWritesUseBorrowedTransactionAfterReaderAcquisition() throws Exception {
		IRI before = FACTORY.createIRI("urn:lifecycle:write:", "before");
		IRI after = FACTORY.createIRI("urn:lifecycle:write:", "after");
		long beforeId = store(before);
		valueStore.clearCaches();

		try (ValueStoreMaterializer materializer = new ValueStoreMaterializer(valueStore)) {
			assertEquals(before.stringValue(), valueStore.getLazyValue(beforeId, materializer).stringValue());

			valueStore.startTransaction(true);
			try {
				long afterId = valueStore.storeValue(after);
				valueStore.clearCaches();
				LmdbIRI lazyAfter = (LmdbIRI) valueStore.getLazyValue(afterId, materializer);
				assertEquals(after.stringValue(), lazyAfter.stringValue(),
						"the owner transaction must provide read-your-writes materialization");
				assertNotEquals(0L, valueStore.currentWriterTransaction(),
						"materializer reads must not close the borrowed writer");
				valueStore.commit();
			} catch (Exception e) {
				valueStore.rollback();
				throw e;
			}

			// A borrowed writer must remain owned by ValueStore after the materializer read returns.
			assertEquals(0L, valueStore.currentWriterTransaction());
			assertEquals(before.stringValue(), valueStore.getLazyValue(beforeId, materializer).stringValue());
		}
	}

	@Test
	void concurrentReadsShareOneMaterializerSafely() throws Exception {
		List<IRI> expected = new ArrayList<>();
		List<Long> ids = new ArrayList<>();
		for (int i = 0; i < 8; i++) {
			IRI value = FACTORY.createIRI("urn:lifecycle:concurrent:", "value-" + i + "-" + "x".repeat(32));
			expected.add(value);
			ids.add(store(value));
		}
		valueStore.clearCaches();

		ExecutorService executor = Executors.newFixedThreadPool(ids.size());
		try (ValueStoreMaterializer materializer = new ValueStoreMaterializer(valueStore)) {
			CountDownLatch ready = new CountDownLatch(ids.size());
			CountDownLatch start = new CountDownLatch(1);
			List<Future<String>> reads = new ArrayList<>(ids.size());
			for (int i = 0; i < ids.size(); i++) {
				long id = ids.get(i);
				reads.add(executor.submit(() -> {
					ready.countDown();
					await(start);
					return valueStore.getLazyValue(id, materializer).stringValue();
				}));
			}

			assertTrue(ready.await(5, TimeUnit.SECONDS), "all concurrent readers must be ready");
			start.countDown();
			for (int i = 0; i < reads.size(); i++) {
				assertEquals(expected.get(i).stringValue(), reads.get(i).get(5, TimeUnit.SECONDS));
			}
		} finally {
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS), "reader workers must terminate");
		}
	}

	@Test
	void materializerCloseRacesLazyDatasetRead() throws Exception {
		IRI expected = FACTORY.createIRI("urn:lifecycle:close-race:", "value-" + "x".repeat(64));
		long id = store(expected);
		valueStore.clearCaches();

		ValueStoreMaterializer materializer = new ValueStoreMaterializer(valueStore);
		ExecutorService executor = Executors.newFixedThreadPool(2);
		CountDownLatch ready = new CountDownLatch(2);
		CountDownLatch start = new CountDownLatch(1);
		try {
			LmdbIRI lazy = (LmdbIRI) valueStore.getLazyValue(id, materializer);
			Future<String> read = executor.submit(() -> {
				ready.countDown();
				await(start);
				return lazy.stringValue();
			});
			Future<?> close = executor.submit(() -> {
				ready.countDown();
				await(start);
				materializer.close();
				return null;
			});

			assertTrue(ready.await(5, TimeUnit.SECONDS), "read and close workers must be ready");
			start.countDown();
			assertEquals(expected.stringValue(), read.get(5, TimeUnit.SECONDS));
			close.get(5, TimeUnit.SECONDS);
			assertEquals(expected.stringValue(), lazy.stringValue(),
					"a read racing materializer close must remain usable through its original revision");
		} finally {
			start.countDown();
			materializer.close();
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS), "close-race workers must terminate");
		}
	}

	@Test
	void valueStoreCloseWaitsForActiveMaterialization() throws Exception {
		IRI expected = FACTORY.createIRI("urn:lifecycle:store-close:", "value-" + "x".repeat(64));
		long id = store(expected);
		valueStore.clearCaches();

		ValueStoreMaterializer materializer = new ValueStoreMaterializer(valueStore);
		ExecutorService executor = Executors.newFixedThreadPool(3);
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch closeEntered = new CountDownLatch(2);
		CountDownLatch release = new CountDownLatch(1);
		Future<String> readTask = null;
		List<Future<?>> closeTasks = new ArrayList<>(2);
		try {
			LmdbIRI template = (LmdbIRI) valueStore.getLazyValue(id, materializer);
			BlockingLmdbIRI blocking = new BlockingLmdbIRI(template.getValueStoreRevision(), id, entered, release);
			readTask = executor.submit(blocking::stringValue);
			assertTrue(entered.await(5, TimeUnit.SECONDS), "materialization must enter native decoding");

			for (int i = 0; i < 2; i++) {
				closeTasks.add(executor.submit(() -> {
					closeEntered.countDown();
					valueStore.close();
					return null;
				}));
			}
			assertTrue(closeEntered.await(5, TimeUnit.SECONDS), "both close workers must enter before release");
			for (Future<?> closeTask : closeTasks) {
				assertThrows(TimeoutException.class, () -> closeTask.get(200, TimeUnit.MILLISECONDS),
						"ValueStore.close must wait for an active native materialization");
			}

			release.countDown();
			assertEquals(expected.stringValue(), readTask.get(5, TimeUnit.SECONDS));
			for (Future<?> closeTask : closeTasks) {
				closeTask.get(5, TimeUnit.SECONDS);
			}
			materializer.close();
			materializer.close();
		} finally {
			release.countDown();
			if (readTask != null) {
				readTask.cancel(true);
			}
			for (Future<?> closeTask : closeTasks) {
				closeTask.cancel(true);
			}
			executor.shutdownNow();
			assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS), "close workers must terminate");
			materializer.close();
		}
	}

	@Test
	void mapGrowthKeepsRetainedReaderUsable() throws Exception {
		ValueStore growthStore = new ValueStore(new File(dataDir, "growth"), config().setValueDBSize(1L << 20));
		try {
			IRI anchor = FACTORY.createIRI("urn:lifecycle:growth:anchor:", "value-" + "x".repeat(128));
			long anchorId = store(growthStore, anchor);
			growthStore.clearCaches();

			try (ValueStoreMaterializer materializer = new ValueStoreMaterializer(growthStore)) {
				assertEquals(anchor.stringValue(), growthStore.getLazyValue(anchorId, materializer).stringValue());
				long initialMapSize = mapSize(growthStore);

				List<IRI> values = new ArrayList<>();
				List<Long> ids = new ArrayList<>();
				long observedMapSize = initialMapSize;
				for (int batch = 0; batch < 8 && observedMapSize == initialMapSize; batch++) {
					growthStore.startTransaction(true);
					try {
						for (int i = 0; i < 64; i++) {
							int valueIndex = batch * 64 + i;
							IRI value = FACTORY.createIRI("urn:lifecycle:growth:" + valueIndex + ":",
									"value-" + "x".repeat(4096));
							values.add(value);
							ids.add(growthStore.storeValue(value));
						}
						growthStore.commit();
					} catch (Exception e) {
						growthStore.rollback();
						throw e;
					}
					observedMapSize = mapSize(growthStore);
				}

				assertTrue(observedMapSize > initialMapSize,
						"the bounded fixture must exercise an actual LMDB map growth");
				growthStore.clearCaches();
				assertEquals(values.get(values.size() - 1).stringValue(),
						growthStore.getLazyValue(ids.get(ids.size() - 1), materializer).stringValue());
				assertEquals(anchor.stringValue(), growthStore.getLazyValue(anchorId, materializer).stringValue());
			}
		} finally {
			growthStore.close();
		}
	}

	private static long mapSize(ValueStore store) throws IOException, ReflectiveOperationException {
		// Observe the native environment without changing private state; this keeps the map-growth assertion tied to
		// LMDB's actual mapsize rather than to a configuration assumption.
		Field envField = ValueStore.class.getDeclaredField("env");
		envField.setAccessible(true);
		long env = envField.getLong(store);
		try (MemoryStack stack = stackPush()) {
			MDBEnvInfo info = MDBEnvInfo.malloc(stack);
			E(mdb_env_info(env, info));
			return info.me_mapsize();
		}
	}

	private static final class BlockingLmdbIRI extends LmdbIRI {

		private final CountDownLatch entered;
		private final CountDownLatch release;

		private BlockingLmdbIRI(ValueStoreRevision revision, long internalID, CountDownLatch entered,
				CountDownLatch release) {
			super(revision, internalID);
			this.entered = entered;
			this.release = release;
		}

		@Override
		public void setNamespaceAndIri(String namespace, String localName) {
			entered.countDown();
			try {
				if (!release.await(5, TimeUnit.SECONDS)) {
					throw new IllegalStateException("Timed out waiting for active materialization release");
				}
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
				throw new IllegalStateException("Interrupted while waiting for active materialization release", e);
			}
			super.setNamespaceAndIri(namespace, localName);
		}
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig()
				.setValueCacheSize(2)
				.setNamespaceCacheSize(2)
				.setValueIDCacheSize(2);
	}

	private long store(Value value) throws IOException {
		return store(valueStore, value);
	}

	private static long store(ValueStore store, Value value) throws IOException {
		store.startTransaction(true);
		try {
			long id = store.storeValue(value);
			store.commit();
			return id;
		} catch (IOException | RuntimeException e) {
			store.rollback();
			throw e;
		}
	}

	private static void await(CountDownLatch latch) throws IOException {
		try {
			if (!latch.await(5, TimeUnit.SECONDS)) {
				throw new IOException("Timed out waiting for lifecycle test coordination");
			}
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new IOException(e);
		}
	}
